/// What [`build_locomotion_graph`] managed to bind.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct LocoBindReport {
    /// `(state, clip name)` for every clip that resolved, in table order.
    pub bound: Vec<(String, String)>,
    /// `(state, clip name)` for every clip that did not.
    pub unbound: Vec<(String, String)>,
    /// States that ended up in the graph.
    pub states: Vec<String>,
    /// States the table names that could not be built at all, because **none**
    /// of their clips resolved.
    pub missing_states: Vec<String>,
}

impl LocoBindReport {
    /// Whether every clip the table names resolved.
    pub fn is_complete(&self) -> bool {
        self.unbound.is_empty()
    }

    /// A one-line summary for an import advisory.
    pub fn summary(&self) -> String {
        format!(
            "{} states, {} clips bound, {} unbound{}",
            self.states.len(),
            self.bound.len(),
            self.unbound.len(),
            if self.missing_states.is_empty() {
                String::new()
            } else {
                format!(" ({} states unfilled)", self.missing_states.len())
            }
        )
    }
}

/// **Build the locomotion graph** from [`LOCOMOTION_MAP`] and a name→clip
/// resolver.
///
/// **Every** row becomes a state, including the overlays and the aim sweeps —
/// and those two families have **no transitions into them**, deliberately.
///
/// A `.inf_sm` is the one asset a character carries that names clips, and the
/// additive layer needs to name some too: an aim offset is three sequences and a
/// weapon overlay is one, and neither is a thing the machine ever *enters*. The
/// alternatives were a second asset kind (a schema, for one `Vec` of GUIDs) or a
/// runtime table nobody could author. So the machine is the character's
/// **animation manifest**, an unreachable state is a named clip set, and
/// `inf_ecs::pose` reads the look sweep off [`LOOK_SWEEP_STATE`] by name. UE's
/// own anim graphs hold their aim offsets exactly this way — as a node in the
/// graph that the state machine does not route through.
///
/// An unreachable state costs one `SmState` in the file and nothing at runtime:
/// `SmRuntime` can only be in a state something transitioned it into.
///
/// A state whose clips all fail to resolve is **left out** rather than pointed at
/// a null GUID: a state that plays nothing is a T-pose with a name, and the
/// report says which ones went. A state whose clips *partly* resolve keeps the
/// samples it has, because a five-sample direction blend is a worse walk and not
/// a broken one.
///
/// The entry state is `idle` when it exists and the first state otherwise.
pub fn build_locomotion_graph(
    resolve: &dyn Fn(&str) -> Option<ClipRef>,
) -> (StateMachine, LocoBindReport) {
    let mut report = LocoBindReport::default();
    let mut states: Vec<SmState> = Vec::new();
    let mut index: std::collections::BTreeMap<&'static str, usize> =
        std::collections::BTreeMap::new();

    for slot in LOCOMOTION_MAP {
        let mut got: Vec<BlendEntry2D> = Vec::new();
        for (name, pos) in slot.clips {
            match resolve(name) {
                Some(clip) => {
                    report.bound.push((slot.state.into(), (*name).into()));
                    got.push(BlendEntry2D { pos: *pos, clip });
                }
                None => report.unbound.push((slot.state.into(), (*name).into())),
            }
        }
        if got.is_empty() {
            report.missing_states.push(slot.state.into());
            continue;
        }
        let motion = if got.len() == 1 {
            Motion::Clip(got[0].clip)
        } else {
            Motion::Blend2D(BlendSpace2D::new(MOVE_X_VAR, MOVE_Y_VAR, got))
        };
        index.insert(slot.state, states.len());
        // The canvas position is the table's own order, laid out in rows of
        // four: an authored graph a human opens should not be a pile at 0,0.
        let n = states.len();
        states.push(SmState {
            name: slot.state.into(),
            motion,
            looping: slot.looping,
            speed: 1.0,
            position: ((n % 4) as f32 * 260.0, (n / 4) as f32 * 180.0),
            on_enter: Vec::new(),
            on_exit: Vec::new(),
        });
        report.states.push(slot.state.into());
    }

    let transitions = transitions_for(&index);
    let entry = index.get("idle").copied().unwrap_or(0);
    (
        StateMachine {
            states,
            transitions,
            entry,
            params: vec![
                SmParam::float(SPEED_VAR),
                SmParam::float(GAIT_VAR),
                SmParam::float(MODE_VAR),
                SmParam::float(GROUNDED_VAR),
                SmParam::float(FALL_SPEED_VAR),
                SmParam::float(LAND_ALPHA_VAR),
                SmParam::float(LANDING_VAR),
                SmParam::float(TIME_SINCE_LAND_VAR),
                SmParam::float(MOVE_X_VAR),
                SmParam::float(MOVE_Y_VAR),
                SmParam::float(TURN_DEG_VAR),
                SmParam::float(PLANTED_FOOT_VAR),
                SmParam::float(FACE_UP_VAR),
            ],
            profiles: Vec::new(),
        },
        report,
    )
}

/// The gait thresholds the graph switches on, m/s.
///
/// `GAIT_VAR` is the 0–3 scale, so these are its own boundaries and not speeds:
/// 1 is walk, 2 run, 3 sprint ([`crate::derive::gait_of`]). Switching on the
/// *scale* rather than on metres per second is what lets one graph serve a
/// 1.6 m character and a 2.0 m one.
const WALK_AT: f64 = 0.1;
/// See [`WALK_AT`].
const RUN_AT: f64 = 1.5;
/// See [`WALK_AT`].
const SPRINT_AT: f64 = 2.5;

/// The cross-fade every locomotion edge uses, seconds.
///
/// ALS's own `Blend Time` on the cycle-blending layers. Long enough to hide the
/// pose discontinuity between two cadences, short enough that the character is
/// not still blending when the player has let go of the stick.
const FADE_S: f64 = 0.15;
/// The fade into and out of an action (a land, a turn, a get-up), which is
/// shorter because an action's first frame is its statement.
const ACTION_FADE_S: f64 = 0.08;

/// Every edge of the graph, over whichever states exist.
///
/// Written as a table over *names* and filtered to the states that were built,
/// so a project with no crouch set gets a graph with no crouch edges rather than
/// a machine that fails `validate`.
fn transitions_for(index: &std::collections::BTreeMap<&'static str, usize>) -> Vec<SmTransition> {
    let mut out = Vec::new();
    let at = |n: &str| index.get(n).copied();

    // ── the gait ladder, inside `Grounded` ───────────────────────────────────
    //
    // Each pair of conditions is an exact complement on the same constant, so
    // the machine cannot chatter and needs no hysteresis band — the rule
    // `locomotion_machine` established at P24.5 and the reason there is no
    // idle→run edge: one fixed step of latency through `walk` buys four edges
    // instead of six.
    let ladder = [
        ("idle", "walk", WALK_AT),
        ("walk", "run", RUN_AT),
        ("run", "sprint", SPRINT_AT),
    ];
    for (lo, hi, at_gait) in ladder {
        if let (Some(a), Some(b)) = (at(lo), at(hi)) {
            out.push(
                SmTransition::on(a, b, FADE_S, GAIT_VAR, CmpOp::Gt, at_gait)
                    .with_curve(BlendCurve::EaseInOut)
                    .when(SmCond::from_flat_and(vec![
                        SmCompare::float(GAIT_VAR, CmpOp::Gt, at_gait),
                        SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Grounded.param()),
                    ])),
            );
            out.push(
                SmTransition::on(b, a, FADE_S, GAIT_VAR, CmpOp::Le, at_gait)
                    .with_curve(BlendCurve::EaseInOut),
            );
        }
    }

    // ── the START, between standing still and walking ───────────────────────
    //
    // ALS's `LocoDetail_Accel_*` is what a character does in its first stride,
    // and it is a one-shot: `idle → start → walk`, with the start priced above
    // the ladder's own `idle → walk` edge so it is not skipped.
    if let (Some(i), Some(st)) = (at("idle"), at("start")) {
        out.push(
            SmTransition::on(i, st, ACTION_FADE_S, GAIT_VAR, CmpOp::Gt, WALK_AT)
                .with_curve(BlendCurve::EaseInOut)
                .with_priority(2),
        );
        if let Some(w) = at("walk") {
            out.push(
                SmTransition::new(st, w, FADE_S)
                    .with_exit_time(0.6)
                    .with_curve(BlendCurve::EaseInOut),
            );
            // …and a start that is abandoned goes back rather than finishing.
            out.push(
                SmTransition::on(st, i, FADE_S, GAIT_VAR, CmpOp::Le, WALK_AT)
                    .with_curve(BlendCurve::EaseInOut)
                    .with_priority(3),
            );
        }
    }

    // ── the STOP, and which foot it is on ───────────────────────────────────
    //
    // ALS ships two stop-down clips because which foot is under you when you
    // stop decides what stopping looks like. The engine publishes the animator's
    // own `FootLock_*` window as `planted_foot`, so the choice is the CLIP's and
    // not this table's; a cycle that authors neither lock takes neither stop and
    // falls through to `idle`, which is the pre-CHAR1b behaviour.
    for (name, foot) in [("stop_l", -0.5), ("stop_r", 0.5)] {
        let Some(st) = at(name) else { continue };
        for from in ["walk", "run", "sprint"] {
            let Some(f) = at(from) else { continue };
            let cmp = if foot < 0.0 { CmpOp::Lt } else { CmpOp::Gt };
            out.push(
                SmTransition::new(f, st, ACTION_FADE_S)
                    .when(SmCond::from_flat_and(vec![
                        SmCompare::float(GAIT_VAR, CmpOp::Le, WALK_AT),
                        SmCompare::float(PLANTED_FOOT_VAR, cmp, foot),
                        SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Grounded.param()),
                    ]))
                    .with_curve(BlendCurve::EaseInOut)
                    .with_priority(6),
            );
        }
        if let Some(i) = at("idle") {
            out.push(
                SmTransition::new(st, i, FADE_S)
                    .with_exit_time(0.7)
                    .with_curve(BlendCurve::EaseInOut),
            );
        }
    }

    // ── TURN IN PLACE ───────────────────────────────────────────────────────
    //
    // P29.4 ported ALS's whole rule set — the delay, the two thresholds, the
    // aim-yaw-rate limit — onto the runtime, and the eight clips crossed the
    // bridge, and no machine could see that a turn was happening. `turn_deg` is
    // the seam: signed, and zero when no turn is running.
    for (stand, crouch, lo, hi, left) in [
        (
            "turn_l90",
            "crouch_turn_l90",
            TURN_MIN_DEG,
            TURN_180_DEG,
            true,
        ),
        (
            "turn_r90",
            "crouch_turn_r90",
            TURN_MIN_DEG,
            TURN_180_DEG,
            false,
        ),
        ("turn_l180", "crouch_turn_l180", TURN_180_DEG, 360.0, true),
        ("turn_r180", "crouch_turn_r180", TURN_180_DEG, 360.0, false),
    ] {
        for (name, from, mode) in [
            (stand, "idle", LocoMode::Grounded),
            (crouch, "crouch_idle", LocoMode::Crouch),
        ] {
            let (Some(to), Some(f)) = (at(name), at(from)) else {
                continue;
            };
            let terms = if left {
                vec![
                    SmCompare::float(TURN_DEG_VAR, CmpOp::Lt, -lo),
                    SmCompare::float(TURN_DEG_VAR, CmpOp::Ge, -hi),
                    SmCompare::float(MODE_VAR, CmpOp::Eq, mode.param()),
                ]
            } else {
                vec![
                    SmCompare::float(TURN_DEG_VAR, CmpOp::Gt, lo),
                    SmCompare::float(TURN_DEG_VAR, CmpOp::Le, hi),
                    SmCompare::float(MODE_VAR, CmpOp::Eq, mode.param()),
                ]
            };
            out.push(
                SmTransition::new(f, to, ACTION_FADE_S)
                    .when(SmCond::from_flat_and(terms))
                    .with_curve(BlendCurve::EaseInOut)
                    // Above the `Any -> idle` / `Any -> crouch_idle` edges, so a
                    // turn is not a race the stance edge wins on some steps.
                    .with_priority(7),
            );
            // A turn plays out and hands back to the stance it came from.
            out.push(
                SmTransition::new(to, f, FADE_S)
                    .with_exit_time(0.9)
                    .with_curve(BlendCurve::EaseInOut),
            );
        }
    }

    // ── crouch: the whole standing family drops into it, and back ────────────
    if let Some(c) = at("crouch_idle") {
        out.push(
            SmTransition::any(c, FADE_S)
                .when(SmCond::from_flat_and(vec![
                    SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Crouch.param()),
                    // **AND STILL** — without this the `Any` edge outvotes the
                    // crouch ladder every step and `crouch_walk` is unreachable,
                    // which is what the reachability arm caught. The same shape
                    // as the `idle` edge below, for the same reason.
                    SmCompare::float(GAIT_VAR, CmpOp::Le, WALK_AT),
                ]))
                .with_curve(BlendCurve::EaseInOut)
                // Below the mode edges below, so an airborne character does not
                // crouch on the way past.
                .with_priority(10),
        );
    }
    if let (Some(ci), Some(cw)) = (at("crouch_idle"), at("crouch_walk")) {
        out.push(
            SmTransition::on(ci, cw, FADE_S, GAIT_VAR, CmpOp::Gt, WALK_AT)
                .with_curve(BlendCurve::EaseInOut),
        );
        out.push(
            SmTransition::on(cw, ci, FADE_S, GAIT_VAR, CmpOp::Le, WALK_AT)
                .with_curve(BlendCurve::EaseInOut),
        );
    }
    if let Some(i) = at("idle") {
        out.push(
            SmTransition::any(i, FADE_S)
                .when(SmCond::from_flat_and(vec![
                    SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Grounded.param()),
                    SmCompare::float(GROUNDED_VAR, CmpOp::Gt, 0.5),
                    SmCompare::float(GAIT_VAR, CmpOp::Le, WALK_AT),
                ]))
                .with_curve(BlendCurve::EaseInOut)
                .with_priority(5),
        );
    }

    // ── the air ──────────────────────────────────────────────────────────────
    for (name, mode) in [
        ("jump", LocoMode::FallFree),
        ("fall", LocoMode::FallControlled),
    ] {
        if let Some(s) = at(name) {
            let mut terms = vec![SmCompare::float(MODE_VAR, CmpOp::Eq, mode.param())];
            if name == "fall" {
                // **AND SLOWLY** — the `Any` edge would otherwise outvote the
                // `fall → fall_fast` edge below on every step and the fast loop
                // would be unreachable. Caught by the reachability arm.
                terms.push(SmCompare::float(FALL_SPEED_VAR, CmpOp::Le, 9.0));
            }
            out.push(
                SmTransition::any(s, ACTION_FADE_S)
                    .when(SmCond::from_flat_and(terms))
                    .with_curve(BlendCurve::EaseInOut)
                    .with_priority(20),
            );
        }
    }
    // A long fall speeds up: ALS swaps `FallLoop` for `FallLoop_Fast`.
    if let (Some(f), Some(ff)) = (at("fall"), at("fall_fast")) {
        out.push(
            SmTransition::on(f, ff, FADE_S, FALL_SPEED_VAR, CmpOp::Gt, 9.0)
                .with_curve(BlendCurve::EaseInOut),
        );
        out.push(
            SmTransition::on(ff, f, FADE_S, FALL_SPEED_VAR, CmpOp::Le, 9.0)
                .with_curve(BlendCurve::EaseInOut),
        );
    }
    // **The landing**, taken off the classifier's LATCH inside a short window
    // after the touch — see [`LANDING_VAR`] for why not off the prediction.
    for (name, kind, prio) in [
        ("land_light", LANDING_SOFT, 30),
        ("land_heavy", LANDING_HARD, 31),
    ] {
        if let Some(s) = at(name) {
            out.push(
                SmTransition::any(s, ACTION_FADE_S)
                    .when(SmCond::from_flat_and(vec![
                        SmCompare::float(GROUNDED_VAR, CmpOp::Gt, 0.5),
                        SmCompare::float(LANDING_VAR, CmpOp::Eq, kind),
                        SmCompare::float(TIME_SINCE_LAND_VAR, CmpOp::Lt, LANDING_WINDOW_S),
                        SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Grounded.param()),
                    ]))
                    .with_curve(BlendCurve::EaseInOut)
                    .with_priority(prio),
            );
        }
    }
    // …and a break-fall goes to the roll rather than to a stand-up.
    if let Some(r) = at("roll") {
        out.push(
            SmTransition::any(r, ACTION_FADE_S)
                .when(SmCond::from_flat_and(vec![
                    SmCompare::float(GROUNDED_VAR, CmpOp::Gt, 0.5),
                    SmCompare::float(LANDING_VAR, CmpOp::Eq, LANDING_ROLL),
                    SmCompare::float(TIME_SINCE_LAND_VAR, CmpOp::Lt, LANDING_WINDOW_S),
                ]))
                .with_curve(BlendCurve::EaseInOut)
                .with_priority(32),
        );
    }
    // …and a landing plays out and hands back to the ladder.
    for name in ["land_light", "land_heavy", "getup_front", "getup_back"] {
        if let (Some(s), Some(i)) = (at(name), at("idle")) {
            out.push(
                SmTransition::new(s, i, ACTION_FADE_S)
                    .with_exit_time(0.9)
                    .with_curve(BlendCurve::EaseInOut),
            );
        }
    }

    // ── roll and ragdoll ─────────────────────────────────────────────────────
    for (name, mode) in [("roll", LocoMode::Roll), ("ragdoll", LocoMode::Ragdoll)] {
        if let Some(s) = at(name) {
            out.push(
                SmTransition::any(s, ACTION_FADE_S)
                    .when(SmCond::float(MODE_VAR, CmpOp::Eq, mode.param()))
                    .with_curve(BlendCurve::EaseInOut)
                    .with_priority(40),
            );
        }
    }
    if let (Some(r), Some(i)) = (at("roll"), at("idle")) {
        out.push(
            SmTransition::new(r, i, ACTION_FADE_S)
                .with_exit_time(0.85)
                .when(SmCond::float(
                    MODE_VAR,
                    CmpOp::Eq,
                    LocoMode::Grounded.param(),
                ))
                .with_curve(BlendCurve::EaseInOut),
        );
    }
    // **Getting up**, and which way up it ended.
    //
    // ALS chooses between its two get-ups by the pelvis's facing, and this
    // engine's ragdoll bridge has recorded that as `RagdollRuntime::face_up`
    // since P29.4 with nothing reading it. It is published now, so both clips
    // are reachable and neither is a default nobody chose.
    //
    // ALS ships only the CROUCHED get-ups (`ALS_CLF_GetUp_Front/Back`); a
    // standing one has to be authored, and is CHAR1b.2's.
    for (name, face_up) in [("getup_front", 0.0), ("getup_back", 1.0)] {
        let (Some(rag), Some(g)) = (at("ragdoll"), at(name)) else {
            continue;
        };
        out.push(
            SmTransition::new(rag, g, ACTION_FADE_S)
                .when(SmCond::from_flat_and(vec![
                    SmCompare::float(MODE_VAR, CmpOp::Eq, LocoMode::Grounded.param()),
                    SmCompare::float(GROUNDED_VAR, CmpOp::Gt, 0.5),
                    SmCompare::float(FACE_UP_VAR, CmpOp::Eq, face_up),
                ]))
                .with_curve(BlendCurve::EaseInOut)
                // **Above the `Any → idle` edge**, or a character that stops
                // ragdolling goes straight to standing and the two get-ups are
                // clips that never play. The reachability arm caught it.
                .with_priority(8),
        );
    }

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every clip resolves to a distinct id, so the graph is fully bound.
    fn all_clips() -> impl Fn(&str) -> Option<ClipRef> {
        |name: &str| {
            let mut id = [0u8; 16];
            for (i, b) in name.as_bytes().iter().enumerate() {
                id[i % 16] ^= *b;
            }
            // A name the table does not use would collide with nothing, which is
            // what makes the `is_complete` claim below mean something.
            Some(id)
        }
    }

    #[test]
    fn the_map_is_a_table_of_distinct_states_and_distinct_clips() {
        let mut states: Vec<&str> = LOCOMOTION_MAP.iter().map(|s| s.state).collect();
        let n = states.len();
        states.sort_unstable();
        states.dedup();
        assert_eq!(states.len(), n, "two slots share a state name");
        let mut clips: Vec<&str> = LOCOMOTION_MAP
            .iter()
            .flat_map(|s| s.clips.iter().map(|(n, _)| *n))
            .collect();
        let m = clips.len();
        clips.sort_unstable();
        clips.dedup();
        assert_eq!(clips.len(), m, "one ALS sequence fills two slots");
        assert!(m >= 60, "the map names only {m} sequences");
    }

    #[test]
    fn a_full_resolve_builds_a_graph_that_validates() {
        let (sm, report) = build_locomotion_graph(&all_clips());
        assert!(report.is_complete(), "unbound: {:?}", report.unbound);
        assert!(report.missing_states.is_empty());
        sm.validate().expect("the built graph validates");
        // Every row is a state — including the overlays and the sweeps, which
        // are the additive layer's named clip sets (see the builder's docs).
        assert_eq!(sm.states.len(), LOCOMOTION_MAP.len(), "{:?}", report.states);
        // …and the two families the machine never enters really have no edge
        // into them, which is what "unreachable" has to mean to be true.
        let sweep = sm
            .states
            .iter()
            .position(|s| s.name == LOOK_SWEEP_STATE)
            .expect("the look sweep is a state");
        assert!(
            !sm.transitions.iter().any(|t| t.to == sweep),
            "something routes into the look sweep"
        );
        assert!(sm.transitions.len() > 20, "{} edges", sm.transitions.len());
        // The direction blends really are blend spaces over the two published
        // axes, and not six states somebody flattened.
        let walk = sm.states.iter().find(|s| s.name == "walk").unwrap();
        match &walk.motion {
            Motion::Blend2D(b) => {
                assert_eq!(b.params, (MOVE_X_VAR.into(), MOVE_Y_VAR.into()));
                assert_eq!(b.entries.len(), 6);
            }
            other => panic!("the walk is not a direction blend: {other:?}"),
        }
    }

    /// **A project with no ALS content still gets a graph** — the CI case.
    #[test]
    fn an_empty_resolve_answers_an_empty_graph_and_says_what_is_missing() {
        let (sm, report) = build_locomotion_graph(&|_| None);
        assert!(sm.states.is_empty());
        assert!(sm.transitions.is_empty());
        assert!(report.bound.is_empty());
        assert_eq!(
            report.unbound.len(),
            LOCOMOTION_MAP.iter().map(|s| s.clips.len()).sum::<usize>()
        );
        assert_eq!(report.missing_states.len(), LOCOMOTION_MAP.len());
        assert!(report.summary().contains("unbound"), "{}", report.summary());
    }

    /// A partial resolve — the crouch set absent — builds the rest and leaves no
    /// dangling edge, which is what `validate` is for.
    #[test]
    fn a_partial_resolve_drops_the_states_it_cannot_fill_and_their_edges() {
        let (sm, report) = build_locomotion_graph(&|name: &str| {
            (!name.contains("CLF")).then(|| all_clips()(name)).flatten()
        });
        sm.validate().expect("a partial graph still validates");
        assert!(
            report
                .missing_states
                .iter()
                .any(|s| s.starts_with("crouch")),
            "{:?}",
            report.missing_states
        );
        assert!(
            !sm.states.iter().any(|s| s.name.starts_with("crouch")),
            "a crouch state was built with no clips"
        );
        assert!(
            sm.states.iter().any(|s| s.name == "walk"),
            "the standing set went with the crouch set"
        );
    }
}
